// Curated question-and-answer knowledge base for the "Ask about this chart" panel.
//
// Answers are written for this site; nothing is generated by a language model.
// - Eligibility is strict: an entry is offered and matched only on the pages, charts and
//   products it declares. A question about another chart is declined, not answered.
// - Numbers have explicit provenance. Every number in an answer is one of: an official
//   constant registered in OFFICIAL with its source; a fixed teaching example declared by
//   the entry; or a fact supplied by the page (computed from the published snapshot or the
//   current simulation) that the entry declares in `uses`. Tests enforce all three rules.
// - When a fact is missing, the sentence that needs it is left out.

export interface AskContext {
  page: string;
  chart: string; // chart identifier, e.g. "overview.curve"
  title: string; // chart title shown in the panel
  scope: string; // human-readable description of the current selection
  facts: Record<string, string>; // verified, pre-formatted values for this selection
  product?: string; // product code of the selected instrument (e.g. "RENDA", "NTNBP"), if any
  explanation?: string; // the chart's own "what it shows / what the data shows" text
}

/** How a fact supplied by a page was obtained. */
export type FactKind = "observed" | "derived" | "scenario" | "date" | "label";

/** Every fact key a page may pass, with its kind. Answers may only use registered keys. */
export const FACT_KINDS: Record<string, FactKind> = {
  bond: "label", family: "label", series: "label", conversion: "date", date: "date", dataAsOf: "date", reference: "date",
  modified: "derived", convexity: "derived", dv01: "derived", percentile: "derived", observations: "observed", current: "observed",
  short: "observed", long: "observed", rateFrom: "observed", rateTo: "observed", rateChange: "derived", from: "date", to: "date",
  priceFrom: "observed", priceTo: "observed", priceChange: "derived", volNow: "derived",
  vnaIpca: "derived", selic: "observed", ipca12: "observed", grossDebt: "observed", grossDebtDate: "date", netDebt: "observed",
  primary: "observed", nominal: "observed", exPostReal: "derived", marketReal: "derived", selicShare: "derived", dpfMonth: "date",
  maturingShare: "observed", avgMaturity: "observed", focusIpca: "observed", focusSelic: "observed", focusYear: "label",
  ipca: "scenario", horizon: "scenario", shock: "scenario", reinvest: "scenario", assumptionsVersion: "label",
  gross: "scenario", net: "scenario", firstTaxRate: "scenario", paymentsAbove15: "scenario", youngestLotDays: "scenario",
  months: "scenario", sample: "observed", w1114: "derived", oos: "derived", worstDrawdown: "observed",
  exactLTN: "derived", exactNTNB: "derived", status: "label", flowYears: "derived", flowFirst: "date", flowLast: "date",
};

/** Official constants that answers may state, each with its source. */
