// ---- matching ----------------------------------------------------------------------------

const SYNONYMS: Record<string, string> = {
  drop: "fall", drops: "fall", fell: "fall", falls: "fall", falling: "fall", decline: "fall", declines: "fall", down: "fall", lower: "fall",
  rises: "rise", rising: "rise", rose: "rise", increase: "rise", increases: "rise", up: "rise", higher: "rise", go: "",
  yields: "rate", yield: "rate", rates: "rate", interest: "rate",
  prices: "price", value: "price", values: "price",
  taxes: "tax", taxed: "tax", taxation: "tax", ir: "tax", irpf: "tax",
  fees: "fee", charges: "fee", charge: "fee",
  payments: "payment", instalments: "payment", installments: "payment", instalment: "payment", installment: "payment", pays: "payment", pay: "payment",
  matures: "maturity", mature: "maturity", maturities: "maturity",
  "renda+": "renda", rendaplus: "renda", aposentadoria: "renda",
  divida: "debt", debts: "debt",
  expectation: "expectations", forecasts: "forecast",
};
const STOP = new Set(["the", "a", "an", "is", "are", "of", "to", "in", "on", "for", "and", "or", "do", "does", "did", "what", "why", "how", "when", "this", "that", "it", "its", "be", "can", "i", "my", "me", "there", "with", "by", "at", "as", "from", "about", "should", "would", "will", "than"]);

function norm(w: string): string {
  let x = SYNONYMS[w] ?? w;
  if (x.length > 4 && x.endsWith("ing")) x = x.slice(0, -3);
  else if (x.length > 4 && x.endsWith("ed")) x = x.slice(0, -2);
  else if (x.length > 3 && x.endsWith("s") && !x.endsWith("ss")) x = x.slice(0, -1);
  return SYNONYMS[x] ?? x;
}

export const tokens = (s: string) => s.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "")
  .split(/[^a-z0-9+%]+/).filter((w) => w.length > 0 && !STOP.has(w)).map(norm).filter((w) => w.length > 0);

/** Whether an entry applies to the given chart context. */
export function eligible(e: Entry, ctx: Pick<AskContext, "page" | "chart" | "product">): boolean {
  const s = e.scope;
  if (s.everywhere) return true;
  const placed = (s.charts?.includes(ctx.chart) ?? false) || (s.pages?.includes(ctx.page) ?? false);
  if (!placed) return false;
  if (!s.products) return true;
  // Product-specific entries require the selected instrument to be one of their products.
  return ctx.product != null && s.products.includes(ctx.product);
}

function specificity(e: Entry, ctx: AskContext): number {
  if (e.scope.charts?.includes(ctx.chart)) return e.scope.products ? 4 : 3;
  if (e.scope.products) return 2;
  if (e.scope.pages) return 1;
  return 0; // site-wide entries come last
}

function score(e: Entry, q: Set<string>): number {
  let sc = 0;
  for (const k of e.keywords) {
    const kt = tokens(k);
    if (!kt.length) continue;
    const hit = kt.filter((w) => q.has(w)).length;
    if (hit === kt.length) sc += kt.length > 1 ? 2 + kt.length : 1.5;
    else if (kt.length > 2 && hit >= 2 && hit / kt.length >= 2 / 3) sc += hit * 0.5;
  }
  for (const w of new Set(tokens(e.q))) if (q.has(w) && w.length > 3) sc += 0.5;
  return sc;
}

export function suggestedQuestions(ctx: AskContext, n = 6): string[] {
  return ENTRIES.filter((e) => eligible(e, ctx))
    .map((e, i) => ({ e, i }))
    .sort((a, b) => specificity(b.e, ctx) - specificity(a.e, ctx) || a.i - b.i)
    .slice(0, n).map(({ e }) => e.q);
}

export interface Answer {
  question: string; answer: string; sources: string[];
  matched: "exact" | "keywords" | "none" | "out-of-scope";
  suggestions: string[];
}

const THRESHOLD = 1.5;

export function answerQuestion(question: string, ctx: AskContext): Answer {
  const pool = ENTRIES.filter((e) => eligible(e, ctx));
  const suggestions = suggestedQuestions(ctx, 4);
  const qNorm = question.trim().toLowerCase();
  const exact = ENTRIES.find((e) => e.q.toLowerCase() === qNorm);
  if (exact) {
    if (pool.includes(exact)) return { question: exact.q, answer: exact.answer(ctx), sources: exact.sources ?? [], matched: "exact", suggestions: [] };
    return { question, answer: "", sources: [], matched: "out-of-scope", suggestions };
  }
  const q = new Set(tokens(question));
  let best: Entry | null = null, bestScore = 0;
  for (const e of pool) {
    const s = score(e, q) * (1 + 0.1 * specificity(e, ctx));
    if (s > bestScore) { bestScore = s; best = e; }
  }
  if (best && bestScore >= THRESHOLD) return { question: best.q, answer: best.answer(ctx), sources: best.sources ?? [], matched: "keywords", suggestions: [] };
  // Recognised, but about another chart or product: say so instead of answering.
  const elsewhere = ENTRIES.filter((e) => !pool.includes(e)).some((e) => score(e, q) >= THRESHOLD + 1);
  return { question, answer: "", sources: [], matched: elsewhere ? "out-of-scope" : "none", suggestions };
}

export const KNOWLEDGE_ENTRIES = ENTRIES.map((e) => ({ id: e.id, q: e.q, scope: e.scope, uses: e.uses ?? [], examples: e.examples ?? [], official: e.official ?? [] }));
/** For tests: run one entry's answer function directly. */
export const answerEntry = (id: string, ctx: AskContext) => ENTRIES.find((e) => e.id === id)!.answer(ctx);
